async function calculate_derivative_and_evaluate() {
  // 1. Calculate the derivative of the polynomial function '3x^3 - 2x^2 + 5x - 7'
  const derivative_function = '3*x^3 - 2*x^2 + 5*x - 7';
  const derivative_at_4 = await tools.calculate_derivative({
    function: derivative_function,
    x_value: 4
  });

  console.log(`Derivative of '3x^3 - 2x^2 + 5x - 7' at x=4: ${derivative_at_4}`);

  // 2. The result of the first calculation is a function of x (the derivative).
  // We need to calculate the derivative of *this* resulting function.
  // The derivative of a polynomial of degree n is a polynomial of degree n-1.
  // The derivative of the first derivative (the second derivative of the original function)
  // will be a polynomial of degree n-2.

  // Since the first derivative is a polynomial, we can represent it as a string
  // and calculate its derivative.
  // The first derivative is: 9x^2 - 4x + 5
  const second_derivative_function = '9*x^2 - 4*x + 5';

  // 3. Evaluate the derivative of the resulting function (the second derivative) at x=2
  const second_derivative_at_2 = await tools.calculate_derivative({
    function: second_derivative_function,
    x_value: 2
  });

  console.log(`Derivative of the first derivative ('9x^2 - 4x + 5') at x=2: ${second_derivative_at_2}`);
}

