async function calculate_total_light_travel_time() {
  const speed_of_light = 299792458; // m/s

  // Distances in light years
  const distance_earth_to_planet1 = 4.22;
  const distance_planet1_to_planet2 = 6.1;
  const distance_planet2_to_earth = 5.88;

  // The light travel time in years is numerically equal to the distance in light years.
  // The total time is the sum of the distances in light years.
  const total_distance_light_years = distance_earth_to_planet1 + distance_planet1_to_planet2 + distance_planet2_to_earth;

  // Calculate the time in seconds for each leg (optional, but good for completeness if we were to use the tool)
  // Time (seconds) = Distance (light years) * (Speed of light in m/s) * (365.25 days/year * 24 hours/day * 60 minutes/hour)
  // A simpler way is to use the light_travel_time tool which takes distance in light years.

  console.log(`Distance 1 (Earth to Planet 1): ${distance_earth_to_planet1} light years`);
  console.log(`Distance 2 (Planet 1 to Planet 2): ${distance_planet1_to_planet2} light years`);
  console.log(`Distance 3 (Planet 2 to Earth): ${distance_planet2_to_earth} light years`);
  console.log(`Total distance: ${total_distance_light_years} light years`);

  // We will use the tool to calculate the time for each segment as requested by the prompt's structure.

  const time1 = await tools.light_travel_time({
    distance_in_light_years: distance_earth_to_planet1,
    speed_of_light: speed_of_light
  });

  const time2 = await tools.light_travel_time({
    distance_in_light_years: distance_planet1_to_planet2,
    speed_of_light: speed_of_light
  });

  const time3 = await tools.light_travel_time({
    distance_in_light_years: distance_planet2_to_earth,
    speed_of_light: speed_of_light
  });

  const total_time_seconds = time1 + time2 + time3;

  console.log(`Time for leg 1 (Earth to Planet 1): ${time1} seconds`);
  console.log(`Time for leg 2 (Planet 1 to Planet 2): ${time2} seconds`);
  console.log(`Time for leg 3 (Planet 2 to Earth): ${time3} seconds`);
  console.log(`Total travel time: ${total_time_seconds} seconds`);
}

