async function perform_chi_squared_test(table: number[], alpha: number): Promise<string> {
  try {
    const result = await tools.chi_squared_test({ table: table, alpha: alpha });
    // The result of chi_squared_test is not explicitly defined,
    // but typically it returns a value that indicates the test statistic and p-value.
    // For this simulation, we will assume the function returns an object with a 'p_value' property.
    // If the actual tool returns a different structure, this part will need adjustment.
    if (typeof result === 'object' && 'p_value' in result) {
      const p_value = result.p_value;
      if (p_value < alpha) {
        return `The Chi-Squared test for the table [${table.join(', ')}] at alpha=${alpha} is statistically significant (p < ${alpha}). There is a significant relationship between the variables in this city.`;
      } else {
        return `The Chi-Squared test for the table [${table.join(', ')}] at alpha=${alpha} is not statistically significant (p >= ${alpha}). There is no significant relationship between the variables in this city.`;
      }
    } else {
      // Fallback if the structure is unexpected
      return `The Chi-Squared test for the table [${table.join(', ')}] could not be interpreted due to an unexpected result format.`;
    }
  } catch (error) {
    return `An error occurred while performing the Chi-Squared test for the table [${table.join(', ')}]: ${error.message}`;
  }
}

