async function estimate_derivative_of_x_squared(x: number): Promise<number> {
  // The function is f(x) = x^2.
  // The derivative is f'(x) = 2x.
  // We will use the estimate_derivative tool to confirm the result.
  const function_name = "x * x"; // A string representation of the function for the tool
  const point = x;
  const dx = 0.0001; // Default increment is fine

  return await tools.estimate_derivative({
    function: function_name,
    x: point,
    dx: dx,
    method: "central"
  });
}

