async function get_mandates(name: string, status: "active" | "pending" | "inactive" | "all" = "all"): Promise<unknown> {
  try {
    if (status === "all") {
      return await tools.partner_mandates({ status: "all" });
    } else {
      return await tools.user_mandates({ name: name, status: status });
    }
  } catch (error) {
    console.error(`Error fetching mandates for ${name} with status ${status}:`, error);
    return null;
  }
}

async function fetch_all_mandates() {
  const users = ["parath", "bhanu"];
  const results: Record<string, any[]> = {};

  for (const user of users) {
    console.log(`Fetching mandates for ${user}...`);
    const activeMandates = await get_mandates(user, "active");
    const pendingMandates = await get_mandates(user, "pending");

    results[user] = {
      active: activeMandates,
      pending: pendingMandates
    };
  }

  console.log("\n--- Results ---");
  console.log(JSON.stringify(results, null, 2));
}

fetch_all_mandates();
